from collections import defaultdict

def group_by_category_and_sort(records):
    grouped = defaultdict(list)

    for record in records:
        category = record.get("category")
        score = record.get("score")

        if category is None or not isinstance(score, (int, float)):
            continue

        grouped[category].append(record)

    for category in grouped:
        grouped[category].sort(key=lambda r: r["score"])

    return dict(grouped)


# Sample input
data = [
    {"id": 1, "category": "fruit", "name": "apple", "score": 7},
    {"id": 2, "category": "fruit", "name": "banana", "score": 3},
    {"id": 3, "category": "vegetable", "name": "carrot", "score": 8},
    {"id": 4, "category": "fruit", "name": "orange", "score": 5},
    {"id": 5, "category": "vegetable", "name": "broccoli", "score": 2},
]

result = group_by_category_and_sort(data)
print(result)
